{
  "type": "object",
  "properties": {
    "complexity": {
      "type": "string",
      "enum": [
        "simple",
        "moderate",
        "complex"
      ],
      "description": "Triage complexity."
    },
    "coverage_assessment": {
      "type": "string",
      "enum": [
        "likely_covered",
        "coverage_question",
        "likely_not_covered"
      ],
      "description": "Coverage view from the policy."
    },
    "fraud_score": {
      "type": "number",
      "description": "Fraud score exactly as returned by the scoring service."
    },
    "fraud_indicators": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Fraud indicators returned or found, each naming its record. Empty if none."
    },
    "recommendation": {
      "type": "string",
      "enum": [
        "fast_track",
        "standard_adjustment",
        "coverage_review",
        "siu_referral"
      ],
      "description": "Recommendation for the adjuster."
    },
    "queue": {
      "type": "string",
      "description": "Adjuster queue to route to."
    },
    "indicative_reserve": {
      "type": "number",
      "description": "Estimated likely cost for the adjuster's reference. Never set on the claim."
    },
    "next_steps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Next steps for the adjuster, for example request repair estimate."
    },
    "confidence": {
      "type": "number",
      "description": "0 to 1. How sure you are that the recommendation is right given what the tools returned. Below 0.5 means you are guessing."
    },
    "rationale": {
      "type": "string",
      "description": "Two to five sentences a reviewer can check against the tool results. Cite the record ids you relied on."
    },
    "questions_for_human": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "If a person has to decide, the specific questions they need to answer. Empty when nothing is open."
    }
  },
  "required": [
    "complexity",
    "coverage_assessment",
    "fraud_score",
    "fraud_indicators",
    "recommendation",
    "queue",
    "indicative_reserve",
    "next_steps",
    "confidence",
    "rationale",
    "questions_for_human"
  ],
  "additionalProperties": false
}

parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Claims adjudication agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize claim').item.json;
const c = $json; // fresh read of the claim with its policy and the latest fraud score
const rec = out?.recommendation;
const pol = c.policy ?? {};
const score = Number(c.fraud?.score);
const reserve = Number(out?.indicative_reserve ?? 0);
const queue = String(out?.queue ?? '');
const standard = (cfg.standard_queues ?? []).includes(queue);
const inForce = pol.status === 'active' && pol.period_start <= req.loss_date && req.loss_date <= pol.period_end;
const today = new Date().toISOString().slice(0, 10);

if (!['new', 'triage'].includes(c.status)) reasons.push('claim status is now ' + c.status);
if (c.assigned_queue) reasons.push('claim is already assigned to ' + c.assigned_queue);
if (Number(c.claimed_amount) !== req.claimed_amount) reasons.push('claimed amount on record ' + c.claimed_amount + ' differs from the event ' + req.claimed_amount);
if (req.loss_date > today) reasons.push('loss date ' + req.loss_date + ' is in the future');
if (req.reported_at && String(req.reported_at).slice(0, 10) < req.loss_date) reasons.push('claim reported before the loss date');
if (!Number.isFinite(score)) reasons.push('no fraud score on record for the claim');
else if (out && Math.abs(Number(out.fraud_score) - score) > 0.001) reasons.push('agent fraud score ' + out.fraud_score + ' differs from the score on record ' + score);
if (!inForce && rec !== 'coverage_review' && rec !== 'siu_referral') reasons.push('policy not in force on the loss date, but recommendation is ' + rec);
if (out?.coverage_assessment !== 'likely_covered' && (rec === 'fast_track' || rec === 'standard_adjustment')) reasons.push('coverage is ' + out?.coverage_assessment + ', recommendation should be coverage review');
if (rec === 'siu_referral' && queue !== cfg.siu_queue) reasons.push('SIU referral must go to ' + cfg.siu_queue + ', not ' + queue);
if (rec === 'siu_referral' && !(out?.fraud_indicators ?? []).length) reasons.push('SIU referral without fraud indicators');
if (rec !== 'siu_referral' && !standard) reasons.push('queue ' + queue + ' is not a configured adjuster queue');
if (reserve < 0) reasons.push('indicative reserve is negative');
if (pol.limit != null && reserve > Number(pol.limit)) reasons.push('indicative reserve ' + reserve + ' above the policy limit ' + pol.limit);
if (rec === 'fast_track' && out?.complexity !== 'simple') reasons.push('fast track proposed for a ' + out?.complexity + ' claim');

// The envelope: a standard queue, not an SIU referral, fraud score under the threshold, small claim and reserve.
const withinEnvelope = rec !== 'siu_referral' && standard && score < cfg.siu_score_threshold
  && req.claimed_amount <= cfg.envelope_max_amount && reserve <= cfg.envelope_max_amount;

const action = {
  type: 'route_claim',
  claim_id: req.claim_id,
  queue,
  recommendation: rec,
  coverage_assessment: out?.coverage_assessment ?? null,
  fraud_score: Number.isFinite(score) ? score : null,
  indicative_reserve_note: reserve,
  next_steps: out?.next_steps ?? [],
};
// Ids, queue, score and amounts only: no claimant detail in Slack.
const summary = 'Claim ' + req.claim_id + ' (' + req.line + ', claimed ' + req.claimed_amount + ' ' + req.currency + ') · fraud score ' + score + '.\n'
  + 'Proposed: route to *' + queue + '* with *' + rec + '* · indicative reserve ' + reserve + ' (a note for the adjuster, not set).\n'
  + (withinEnvelope ? '' : 'Needs the supervisor because: ' + [rec === 'siu_referral' ? 'SIU referral' : '', score >= cfg.siu_score_threshold ? 'fraud score at or above ' + cfg.siu_score_threshold : '', Math.max(req.claimed_amount, reserve) > cfg.envelope_max_amount ? 'amount above ' + cfg.envelope_max_amount : ''].filter(Boolean).join(', ') + '.');
const ok = reasons.length === 0;
const isNoop = typeof noop !== 'undefined' && noop === true;
const route = !ok ? 'escalate' : isNoop ? 'none' : withinEnvelope ? 'auto' : 'approve';
return { json: { business_key: req.business_key, route, within_envelope: withinEnvelope, guardrail_reasons: reasons, action, approval_summary: summary, planned_actions: ok && !isNoop ? [action] : [] } };

// The approval request goes to one named person, so the approver is that person.
// Slack returns { data: { approved, respondedAt } }; a timeout resumes without it.
const cfg = $('Config').first().json;
const approved = $json.data?.approved;
return {
  json: {
    decision: approved === true ? 'approved' : approved === false ? 'declined' : 'timed_out',
    approver: cfg.approver_slack_user,
    decided_at: $json.data?.respondedAt ?? new Date().toISOString(),
    handoff_reason: approved === true || approved === false ? '' : 'approval timed out after ' + cfg.approval_timeout_hours + ' hours',
  },
};

// Done only when the system of record shows what was planned.
const planned = $('Guardrails').item.json.action;
const untouched = ($json.payments ?? []).length === 0 && ($json.reserve == null || Number($json.reserve) === 0) && $json.status !== 'denied';
const ok = $json.assigned_queue === planned.queue && $json.recommendation?.type === planned.recommendation && untouched;
const detail = 'claim shows queue ' + $json.assigned_queue + ', recommendation ' + $json.recommendation?.type + ', status ' + $json.status + ', reserve ' + $json.reserve
  + '; expected ' + planned.queue + '/' + planned.recommendation + (untouched ? '' : ', and no payment, reserve or denial');
return { json: { verified: ok, verify_failed: !ok, verify_detail: ok ? '' : detail } };

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize claim').item.json;
let agent = null;
let guard = null;
try { agent = $('Claims adjudication agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "claims operations",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Claim ' + intake.claim_id + ' · ' + intake.line + ' · proposed ' + (agent?.output?.recommendation ?? 'none') + ' to ' + (agent?.output?.queue ?? 'no queue'),
  },
};

parameters.query:
INSERT INTO agent_exceptions (workflow, business_key, team, reasons, proposed_action, confidence, questions, trace, summary, n8n_execution_id)
VALUES ($1, $2, $3, $4::jsonb, $5::jsonb, $6, $7::jsonb, $8::jsonb, $9, $10)
RETURNING id;

parameters.jsCode:
const intake = $('Normalize claim').item.json;
let agent = null;
let guard = null;
let approval = null;
try { agent = $('Claims adjudication agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}
// Present only on workflows with a named-approver step, and only if this run reached it.
try { approval = $('Record approval').item.json; } catch (e) {}

return {
  json: {
    business_key: intake.business_key,
    outcome: $json.outcome,
    approval: approval ? { decision: approval.decision, approver: approval.approver, decided_at: approval.decided_at } : null,
    route: guard?.route ?? 'escalate',
    decision: agent?.output ?? null,
    guardrail_reasons: guard?.guardrail_reasons ?? [],
    actions: guard?.planned_actions ?? [],
    tool_calls: (agent?.intermediateSteps ?? []).length,
  },
};
